// Generates src/styles/tokens.css (CSS custom properties) from the design tokens of the change
// (docs/specs/CHG-0001/design/ux/tokens.json, decision DD-1). Run with `pnpm tokens`. Semantic tokens only:
// UI code never uses the primitives. Change the tokens, never the generated file.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..', '..');
const source = resolve(root, 'docs/specs/CHG-0001/design/ux/tokens.json');
const target = resolve(root, 'web/src/styles/tokens.css');
const tokens = JSON.parse(readFileSync(source, 'utf8'));

function lookup(path) {
  let node = tokens;
  for (const part of path.split('.')) node = node?.[part];
  if (!node || node.$value === undefined) throw new Error(`unknown token reference {${path}}`);
  return node.$value;
}

function resolveValue(value) {
  if (typeof value === 'string') {
    const reference = /^\{([^}]+)\}$/.exec(value);
    return reference ? resolveValue(lookup(reference[1])) : value;
  }
  return value;
}

function toCss(type, value) {
  const v = resolveValue(value);
  if (type === 'fontFamily') return v.map((name) => (name.includes(' ') ? `"${name}"` : name)).join(', ');
  if (type === 'cubicBezier') return `cubic-bezier(${v.join(', ')})`;
  if (type === 'shadow') return `${v.offsetX} ${v.offsetY} ${v.blur} ${v.spread} ${v.color}`;
  return String(v);
}

const lines = [];
function walk(node, path) {
  for (const [key, child] of Object.entries(node)) {
    if (key.startsWith('$') || (path.length === 0 && key === 'primitive')) continue;
    if (child.$value !== undefined) {
      if (child.$type === 'typography') {
        for (const [prop, ref] of Object.entries(child.$value)) {
          const kind = prop === 'fontFamily' ? 'fontFamily' : 'plain';
          lines.push(`  --${[...path, key, prop].join('-')}: ${toCss(kind, ref)};`);
        }
        continue;
      }
      lines.push(`  --${[...path, key].join('-')}: ${toCss(child.$type, child.$value)};`);
    } else {
      walk(child, [...path, key]);
    }
  }
}
walk(tokens, []);

writeFileSync(
  target,
  `/* GENERATED by web/scripts/generate-tokens.mjs from docs/specs/CHG-0001/design/ux/tokens.json. Do not edit. */\n:root {\n${lines.join('\n')}\n}\n`,
);
